// ============================================================================
// ГЛОБАЛЬНЫЕ НАСТРОЙКИ ТЕМЫ
// ============================================================================
// Этот файл содержит базовые настройки темы: цветовую палитру, типографику,
// скругления и другие глобальные параметры, которые используются всеми компонентами
// ============================================================================

// Светлая тема - палитра цветов
export const lightPalette = {
    mode: 'light' as const, // 'as const' указывает TypeScript, что это литеральное значение 'light', а не строка

    primary: { // Основной цвет бренда (лавандовый)
        main: '#134ee3', // Основной цвет - используется для кнопок, акцентов, важных элементов
        light: '#D8CFF0', // Светлый вариант - для фонов, hover состояний
        dark: '#280feb', // Темный вариант - для активных состояний, нажатий
        contrastText: '#FFFFFF', // Цвет текста на фоне основного цвета (должен контрастировать)
    },

    secondary: { // Второстепенный цвет бренда (персиковый)
        main: '#000000', // Основной второстепенный цвет
        light: '#FFE8DC', // Светлый вариант
        dark: '#000000', // Темный вариант
        contrastText: '#000000', // Цвет текста на фоне второстепенного цвета
    },

    background: { // Фоновые цвета
        default: '#2b48eb', // Цвет фона всего приложения (кремовый)
        paper: '#FFFFFF', // Цвет фона для "поверхностей" (карточки, меню, модальные окна)
    },

    error: { // Цвет для ошибок и предупреждений
        main: '#d55c5c', // Основной цвет ошибки (пастельный красный)
    },

    warning: { // Цвет для предупреждений
        main: '#f47#d55c5c356', // Основной цвет предупреждения (пастельный желтый)
    },

    info: { // Цвет для информационных сообщений
        main: '#B5D0D9', // Основной информационный цвет (пастельный голубой)
    },

    success: { // Цвет для сообщений об успехе
        main: '#C3E3C9', // Основной цвет успеха (пастельный зеленый)
    },

    text: { // Цвета текста
        primary: '#5E4B4B', // Основной цвет текста (для заголовков, основного контента)
        secondary: '#7F6B6B', // Второстепенный цвет текста (для подписей, менее важного текста)
        disabled: '#B0B0B0', // Цвет для отключенного текста
    },

    divider: '#E0E0E0', // Цвет разделительных линий
};

// Темная тема - палитра цветов
export const darkPalette = {
    mode: 'dark' as const,

    primary: { // Основной цвет для темной темы (более яркий для контраста)
        main: '#B39DDB', // Более яркий лавандовый для лучшей видимости
        light: '#D1C4E9',
        dark: '#7C6B9C',
        contrastText: '#FFFFFF',
    },

    secondary: { // Второстепенный цвет для темной темы
        main: '#FFB59E', // Более яркий персиковый
        light: '#FFD5C4',
        dark: '#D48C75',
        contrastText: '#1A1A1A', // Темный текст для контраста на светлом фоне
    },

    background: {
        default: '#121212', // Очень темный фон для приложения
        paper: '#1E1E1E', // Чуть светлее для карточек
    },

    error: {
        main: '#CF6679', // Стандартный красный для темной темы Material Design
    },

    warning: {
        main: '#FFB74D', // Яркий оранжевый
    },

    info: {
        main: '#64B5F6', // Яркий голубой
    },

    success: {
        main: '#81C784', // Яркий зеленый
    },

    text: {
        primary: '#FFFFFF', // Белый для максимального контраста
        secondary: '#B0B0B0', // Светло-серый для второстепенного текста
        disabled: '#666666', // Темно-серый для отключенного
    },

    divider: '#333333', // Темный разделитель
};

// Глобальные настройки типографики
export const typography = {
    fontFamily: '"Roboto", "Helvetica", "Arial", sans-serif', // Шрифты по умолчанию
    h4: { // Стили для заголовков h4
        fontWeight: 500, // Полужирный
        fontSize: '2rem', // Размер шрифта
        lineHeight: 1.2, // Межстрочный интервал
        marginBottom: '1rem', // Отступ снизу
    },
    h6: {
        fontWeight: 500,
        fontSize: '1.25rem',
        lineHeight: 1.6,
    },
    body1: { // Основной текст
        fontSize: '1rem',
        lineHeight: 1.5,
    },
    body2: { // Второстепенный текст (меньшего размера)
        fontSize: '0.875rem',
        lineHeight: 1.43,
    },
    button: { // Стили для текста на кнопках
        textTransform: 'none', // Отключаем автоматический uppercase
        fontWeight: 500,
    },
};

// Глобальные настройки формы (скругления)
export const shape = {
    borderRadius: 12, // Базовое скругление углов для всех компонентов
};

// Общие настройки теней
export const shadows = {
    light: {
        card: '0 4px 12px rgba(181, 168, 213, 0.15)', // Тень для карточек в светлой теме
        cardHover: '0 8px 24px rgba(181, 168, 213, 0.25)', // Тень при наведении
        button: '0 2px 8px rgba(181, 168, 213, 0.2)', // Тень для кнопок
        appBar: '0 2px 8px rgba(181, 168, 213, 0.15)', // Тень для AppBar
    },
    dark: {
        card: '0 4px 12px rgba(0, 0, 0, 0.5)', // Более темная тень для темной темы
        cardHover: '0 8px 24px rgba(0, 0, 0, 0.7)',
        button: '0 2px 8px rgba(0, 0, 0, 0.3)',
        appBar: '0 2px 8px rgba(0, 0, 0, 0.5)',
    },
};
